{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"Landlords may raise rent only once every 12 months by the allowable percentage; since February 2, 2026 the extra utility increase and the 10% additional-dependent increase are barred, and limited surcharges for registration and smoke detectors may be passed through.","key_value":"Allowable rent increase percentage, once every 12 months","coverage_conditions":"Generally, rental property in the City of Los Angeles first built on or before October 1, 1978, including replacement units under LAMC § 151.28, and listed unit types such as apartments, condominiums, townhomes, duplexes, ADUs and mobile homes.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","text":"Luxury exemption: landlord may apply to LAHD if the monthly rent charged on or before May 31, 1978 met the threshold"}],"per_tenancy":"Condominium and townhome rent amounts are not regulated for tenancies that commenced after December 31, 1995; hotel, motel, rooming or boarding house rooms are covered only when the same tenant occupies them more than 30 consecutive days.","coverage_quotes":["the RSO applies to rental properties that were first built on or before October 1, 1978","Condominium (Rent amount is not regulated for tenancies that commenced after December 31, 1995)","A landlord can apply for an exemption from the RSO if they can establish the monthly rent charged on or before May 31, 1978,*."]},"exemptions":"Condominium and townhome rent amounts are not regulated for tenancies that commenced after December 31, 1995; a landlord may apply for the luxury exemption based on the rent charged on or before May 31, 1978.","penalty":null,"effective_date":"2026-02-02","valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction and relocation assistance","requirement":"Landlords may evict RSO tenants only for the listed at-fault or no-fault reasons, must file every termination notice with LAHD within three business days of service, and must pay relocation assistance for no-fault evictions.","key_value":"3 business days to file termination notices; relocation assistance for no-fault evictions","coverage_conditions":"All rental units subject to the City of Los Angeles Rent Stabilization Ordinance; rental units not covered by the RSO fall under the city's Just Cause Ordinance.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["the RSO applies to rental properties that were first built on or before October 1, 1978"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"L.A.M.C. § 151.09","quoted_span":"must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant per Los Angeles Municipal Code 151.09.C.9 & 165.05.B.5.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
